package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.WorkerAuthorizationService.*;
import java.time.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.LongPredicate;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.*;

/** Controlled preflight port only; native reservation is real, no original INPUT claim. */
class WorkerCandidateSelectionScopeTest {
    WorkerCandidatePageTest f;JdbcWorkerState state;JdbcJobRecords records;DispatchReadinessService readiness;
    WorkerJdbcStore store;WorkerAuthorizationService worker;Clock clock;AtomicInteger reads;boolean paused;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    static void installWorker(GenerationJdbcStoreTest db){String time=db.source instanceof org.h2.jdbcx.JdbcDataSource?"TIMESTAMP(6)":"DATETIME(6)";if(db.source instanceof org.h2.jdbcx.JdbcDataSource)db.jdbc.execute("CREATE ALIAS UNHEX FOR 'com.lianxibu.site.service.jobs.ResultJdbcStoreTest.unhex'");for(String c:new String[]{"slot_state VARCHAR(16) DEFAULT 'free'","slot_revision BIGINT DEFAULT 0","fencing_token BIGINT DEFAULT 0","job_id VARCHAR(64)","holder VARCHAR(64)","lease_until "+time,"request_deadline "+time,"occupied_since "+time})db.jdbc.execute("ALTER TABLE worker_lock ADD "+c);for(String c:new String[]{"worker_instance_id VARCHAR(64)","dispatch_token BIGINT","request_deadline "+time,"send_authorized_at "+time,"slot_released_at "+time,"release_reason VARCHAR(32)"})db.jdbc.execute("ALTER TABLE jobs ADD "+c);}
    void setup(int count){f=new WorkerCandidatePageTest(){@Override GenerationJdbcStoreTest database(){return WorkerCandidateSelectionScopeTest.this.database();}};f.setup(count);installWorker(f.f);state=f.service;records=new JdbcJobRecords(f.f.source);clock=Clock.fixed(f.now,ZoneOffset.UTC);for(int n=0;n<count;n++)f.f.jdbc.update("UPDATE jobs SET request_json=? WHERE id=?",request(n),String.format(java.util.Locale.ROOT,"attempt-fictional-page-%03d",n));f.f.jdbc.update("UPDATE jobs SET priority_no=1 WHERE record_kind='logical_task'");readiness=mock(DispatchReadinessService.class);reads=new AtomicInteger();when(readiness.preflight(any())).thenAnswer(c->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertTrue(TransactionSynchronizationManager.isCurrentTransactionReadOnly());reads.incrementAndGet();return true;});when(readiness.captureSource(any())).thenAnswer(c->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return null;});when(readiness.ready(any())).thenAnswer(c->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());return true;});store=provider(seen->true);worker=new WorkerAuthorizationService(f.f.writes,store,clock,n->0,()->true);}
    String request(int n){return "{\"provider\":\"deepseek\",\"model\":\"deepseek-flash\",\"messages\":[{\"role\":\"user\",\"content\":\"Fictional selection "+n+"\"}],\"parameters\":{},\"response_format\":{\"type\":\"json_object\"},\"schema_version\":\"fixture\",\"prompt_version\":\"fixture\",\"input_hash\":\""+"a".repeat(64)+"\"}";}
    WorkerJdbcStore provider(LongPredicate choice){return new WorkerJdbcStore(state,records,"fictional-selection-owner",()->paused,readiness,clock,new DataSourceTransactionManager(f.f.source),choice);}
    SharedWriteExecutor.ActionContext action(){return new SharedWriteExecutor.ActionContext("fictional-native-selection","fictional-selection-receipt",null);}
    @Test void All103SamePriorityCandidatesAreVisitedAcrossPagesBeforeOneActualReservation(){setup(103);String expected=f.read(()->state.candidates(f.now)).getLast().root();var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());assertEquals(expected,claim.permit().identity().rootId());assertEquals(103,reads.get());verify(readiness,times(1)).ready(expected);assertEquals(1,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(1,f.f.count("target_type='worker_claim'"));doThrow(new IllegalStateException("fictional unrelated queue unavailable")).when(readiness).preflight(any());worker=new WorkerAuthorizationService(f.f.writes,provider(seen->true),clock,n->0,()->true);assertEquals(claim.permit().identity(),worker.claim(action()).permit().identity());assertEquals(103,reads.get());assertEquals(1,f.f.count("target_type='worker_claim'"));}
    @Test void LowerPriorityIsChosenOnlyAfterAllHigherCandidatesFailPreflightAndBadRequestsAreSkipped(){setup(103);f.f.jdbc.update("UPDATE jobs SET priority_no=2 WHERE id='root-fictional-page-102'");f.f.jdbc.update("UPDATE jobs SET request_json='{}' WHERE id='attempt-fictional-page-000'");doAnswer(c->{assertTrue(TransactionSynchronizationManager.isCurrentTransactionReadOnly());return "root-fictional-page-102".equals(c.getArgument(0));}).when(readiness).preflight(any());var claim=worker.claim(action());assertEquals(State.CLAIMED,claim.state());assertEquals("root-fictional-page-102",claim.permit().identity().rootId());verify(readiness,never()).preflight("root-fictional-page-000");verify(readiness,times(102)).preflight(any());assertEquals(1,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));}
    @Test void CapturedActionRolesAndChangedNativeHeadersCannotReserve(){setup(1);var scope=store.captureClaim(action(),f.now);assertThrows(RuntimeException.class,()->scope.candidates(f.now));var tx=new TransactionTemplate(new DataSourceTransactionManager(f.f.source));var chosen=tx.execute(s->scope.candidates(f.now)).getFirst();assertThrows(RuntimeException.class,()->tx.execute(s->scope.reserve(chosen,"fictional-hint",f.now.plusSeconds(150),f.now,"fictional-wrong-action")));f.f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",chosen.rootId());assertThrows(RuntimeException.class,()->tx.execute(s->scope.candidates(f.now)));assertEquals(0,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(0,f.f.count("target_type='worker_claim'"));verify(readiness,never()).ready(any());}
    @Test void PausedDefaultGateAndNoReadyCandidatesPersistNoReservation(){setup(3);paused=true;assertEquals(State.IDLE,worker.claim(action()).state());assertEquals(0,reads.get());paused=false;worker=new WorkerAuthorizationService(f.f.writes,store,clock);assertEquals(State.IDLE,worker.claim(action()).state());doReturn(false).when(readiness).preflight(any());worker=new WorkerAuthorizationService(f.f.writes,store,clock,n->0,()->true);assertEquals(State.IDLE,worker.claim(action()).state());assertEquals("free",state.slot().state());assertEquals(0,f.f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(0,f.f.count("target_type='worker_claim'"));}
}
